create or replace TABLE SZD_PRODUCTION.CORE.T_FACT_DEPOSIT_RETURN_OUTPAYMENT_2 (
	RVM_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the despotie machine which is located in a store',
	CAL_DT DATE NOT NULL COMMENT 'The day represented as a calendar_2 date of the form YYYY-MM_2-DD. YYYY is the calendar_2 year, MM_2 (between 1 and 12) the calendar_2 month and DD the day of the calendar_2 month (between 1 and 31). ',
	DEPOSIT_ITEM_SUB_CAT_ID NUMBER(38,0) NOT NULL COMMENT 'The id for the item_2 return type',
	DEPOSIT_OUTPAYMENT_TYPE_CD VARCHAR(50) NOT NULL COMMENT 'The code for the way how the deposit amount can be paid back to the customer. (outpayment / donation / QR code / ...',
	RECEIPT_CNT NUMBER(38,0) NOT NULL COMMENT 'The Distinct number of customers who deposited at least one item_2 of the deposit item_2 class ( this measure is not additive)',
	RECEIPT_GROSS_LOCAL_VAL NUMBER(38,5) NOT NULL COMMENT 'The total gross amount in local currency of deposits generated by a deposit machine on this day.',
	RECEIPT_GROSS_GLOBAL_VAL NUMBER(38,5) NOT NULL COMMENT 'The total gross amount in global currency of deposits generated by a deposit machine on this day.',
	GLOBAL_CURR_CD VARCHAR(3) NOT NULL COMMENT 'The global currency code-now it is set as EUR',
	LOCAL_CURR_CD VARCHAR(3) NOT NULL COMMENT 'The local currency code',
	DWH_CREATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was inserted into the table.',
	DWH_UPDATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was last modified. (In case the record has not been modified since its creation, dwh_updated is identical to dwh_created.)',
	constraint PK_T_FACT_DEPOSIT_RETURN_OUTPA primary key (CAL_DT, RVM_SID, DEPOSIT_ITEM_SUB_CAT_ID, DEPOSIT_OUTPAYMENT_TYPE_CD)
)COMMENT='Mixed (aggregated and transactional) facts capturing the count and sum of receipts'
;